type Stream struct{ buf *Buffer }
func NewStream(buf *Buffer) Stream { return Stream{buf: buf} }

type Output struct {
    Stream                        // embedding borrows the methods
    buf    *Buffer
}

func NewOutput(fd int) *Output {
    b := NewBuffer(fd)                   // payload first,
    return &Output{Stream: NewStream(b), buf: b}   // then the dependent part
}
